BEGIN;
CREATE TABLE meters.meters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),unit_code text NOT NULL REFERENCES core.units(code),location_note text NOT NULL DEFAULT '',archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id));
CREATE TABLE meters.devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),meter_id uuid NOT NULL,serial_number text NOT NULL DEFAULT '',installed_on date NOT NULL,removed_on date,initial_reading numeric(18,6) NOT NULL CHECK(initial_reading>=0),rollover_value numeric(18,6) CHECK(rollover_value>0),created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,meter_id) REFERENCES meters.meters(household_id,id),CHECK(removed_on IS NULL OR removed_on>=installed_on));
CREATE TABLE meters.readings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),device_id uuid NOT NULL,measured_at timestamptz NOT NULL,value numeric(18,6) NOT NULL CHECK(value>=0),kind text NOT NULL DEFAULT 'actual' CHECK(kind IN('actual','estimated')),note text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(device_id,measured_at),FOREIGN KEY(household_id,device_id) REFERENCES meters.devices(household_id,id));
CREATE INDEX readings_device ON meters.readings(household_id,device_id,measured_at,id);
GRANT USAGE ON SCHEMA meters TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA meters TO household_app;
COMMIT;
